const cache=await caches.open(CACHE);
await cache.add('./');
await Promise.all(CORE.filter(path=>path!=='./').map(async path=>{
  try{
    const response=await fetch(path,{cache:'reload'});
    if(response.ok) await cache.put(path,response.clone());
  }catch{/* An optional icon must never block the shell upgrade. */}
}));

self.addEventListener('activate',event=>{
 event.waitUntil((async()=>{
   const keys=await caches.keys();
   const previous=keys.filter(key=>key.startsWith('trabajo-cerca-shell-icons-')&&key!==CACHE).sort().reverse();
   const preserve=new Set([CACHE,SHARE_CACHE,...previous.slice(0,4)]);
   await Promise.all(previous.filter(key=>!preserve.has(key)).map(key=>caches.delete(key)));
   await self.clients.claim();
 })());
});
